function translateUI(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';if(state.lang!=='ar')return;const walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){const v=n.nodeValue.trim();if(translations[v])n.nodeValue=n.nodeValue.replace(v,translations[v]);}}

async function api(path,opts={}){const r=await fetch(path,{credentials:'same-origin',headers:{'content-type':'application/json',...(opts.headers||{})},...opts});let d=null;try{d=await r.json()}catch{}if(!r.ok)throw new Error(d?.error||'Request failed');return d}
function fmtDate(v){return v?new Date(v.replace(' ','T')+'Z').toLocaleString():''}
function layout(content,opts={}){const adminPortal=isAdminPortal();const ar=state.lang==='ar';const nav=adminPortal?`<nav class="site-nav"><button onclick="adminTab('overview')">${ar?'الرئيسية':'Home'}</button><button onclick="adminTab('exams')">${ar?'الامتحانات':'Exams'}</button><button onclick="adminTab('results')">${ar?'النتائج':'Results'}</button><a href="https://case-lab.pages.dev/" target="_blank" rel="noopener noreferrer">case-lab</a></nav>`:`<nav class="site-nav"><button onclick="go('home')">${ar?'الرئيسية':'Home'}</button><button onclick="go('dashboard')">${ar?'الامتحانات':'Exams'}</button><button onclick="go('results')">${ar?'النتائج':'Results'}</button><a href="https://case-lab.pages.dev/" target="_blank" rel="noopener noreferrer">case-lab</a></nav>`;const auth=adminPortal?(state.me?.admin?`<button class="btn" onclick="logout()">${ar?'تسجيل الخروج':'Logout'}</button>`:''):state.me?.user?`<button class="btn ghost" onclick="go('dashboard')">${ar?'لوحة التحكم':'Dashboard'}</button><button class="btn" onclick="logout()">${ar?'تسجيل الخروج':'Logout'}</button>`:`<button class="btn ghost" onclick="go('login')">${ar?'دخول الطالب':'Student Login'}</button><button class="btn orange" onclick="go('register')">${ar?'ابدأ الآن':'Get started'}</button>`;return `<div class="shell"><header class="topbar"><div class="brand"><img class="brand-logo" src="/ae-logo.png" alt="AE"><div class="brand-name">Ahmed Elsheshtawy<small>Ahmed Finance · EXAM PLATFORM</small></div></div>${nav}<div class="top-actions"><button class="circle-btn" onclick="toggleLang()" aria-label="Language">${ar?'EN':'AR'}</button><button class="circle-btn theme-btn" onclick="toggleTheme()" aria-label="Theme">${state.theme==='dark'?'☼':'✦'}</button>${auth}<a class="connect-btn" href="https://ahmed-portfolio.ahmedelsheshtawyofficial.workers.dev/#contact" target="_blank" rel="noopener noreferrer">${ar?'تواصل معي ↗':"Let's Connect ↗"}</a></div></header>${content}<footer class="footer">Numbers tell a story. I analyze it. · Ahmed Elsheshtawy</footer></div>`}
async function boot(){applyTheme();try{state.me=await api('/api/auth/me')}catch{}const adminPortal=isAdminPortal();if(adminPortal)state.view=state.me?.admin?'admin':'admin-login';else state.view=state.me?.user?'dashboard':'home';render()}
function render(){const adminPortal=isAdminPortal();if(adminPortal){if(state.view==='admin'&&state.me?.admin)return renderAdmin();return renderAdminLogin()}if(state.view==='admin-login'||state.view==='admin')state.view='home';if(state.me?.user&&state.view==='home')state.view='dashboard';if(state.view==='login')return renderLogin();if(state.view==='register')return renderRegister();if(state.view==='dashboard'&&state.me?.user)return renderDashboard();if(state.view==='exam'&&state.me?.user)return renderExam();if(state.view==='result')return renderResult(state.lastResult);state.view='home';renderHome()}
function renderHome(){app.innerHTML=layout(`<main class="home-page"><section class="home-hero"><div class="home-copy"><div class="home-kicker"><span class="home-dot"></span> Finance learning · assessment · performance</div><h1>Assess what you know.<br><span>Measure what you can do.</span></h1><p>A focused assessment workspace for finance learners — built around real exams, timed performance and clear results.</p></div><div class="home-entry"><button class="entry-card entry-primary" onclick="go('register')"><span class="entry-number">01</span><span class="entry-content"><small>NEW STUDENT</small><strong>Get started</strong><em>Create your student account and receive your Student ID.</em></span><span class="entry-arrow">↗</span></button><button class="entry-card" onclick="go('login')"><span class="entry-number">02</span><span class="entry-content"><small>ALREADY REGISTERED</small><strong>Student Login</strong><em>Continue to your dashboard and active assessments.</em></span><span class="entry-arrow">↗</span></button></div></section></main>`)}
function renderAdminLogin(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">Administration</div><h1>Control center.</h1><p class="muted">Authorized administrators only.</p><form class="form" onsubmit="adminLogin(event)"><div class="field"><label>Username</label><input name="username" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn orange">Admin Login</button></form><p class="small-text muted">Student? <span class="link" onclick="go('login')">Student login</span></p></div></div></main>`)}
async function adminLogin(e){e.preventDefault();const f=new FormData(e.target);try{await api('/api/admin/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');state.view='admin';render()}catch(x){showToast(x.message)}}
function renderLogin(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">Student access</div><h1>Welcome back.</h1><p class="muted">Use your Student ID or email and password.</p><form class="form" onsubmit="studentLogin(event)"><div class="field"><label>Student ID / Email</label><input name="identifier" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn orange">Login</button></form><p class="small-text muted">No account? <span class="link" onclick="go('register')">Register here</span></p></div></div></main>`)}
function renderRegister(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">New student</div><h1>Create your account.</h1><p class="muted">Your Student ID is generated automatically. You will see it immediately after registration.</p><form class="form" onsubmit="studentRegister(event)"><div class="field"><label>Full name</label><input name="fullName" required maxlength="120"></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" maxlength="128" required></div><button class="btn orange">Register & Get Student ID</button></form><p class="small-text muted">Already registered? <span class="link" onclick="go('login')">Login</span></p></div></div></main>`)}
async function studentLogin(e){e.preventDefault();const f=new FormData(e.target);try{await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');showToast('Login successful');go('dashboard')}catch(x){showToast(x.message)}}
async function studentRegister(e){e.preventDefault();const f=new FormData(e.target);try{const d=await api('/api/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');app.innerHTML=layout(`<main class="page"><div class="center"><div class="card result-box"><div class="eyebrow">Registration complete</div><h2>Your Student ID</h2><div class="score">${esc(d.studentId)}</div><p class="muted">Save this ID. You can use it or your email to log in.</p><button class="btn orange" onclick="go('dashboard')">Continue to Dashboard</button></div></div></main>`)}catch(x){showToast(x.message)}}
async function logout(){await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.me=null;state.view=(isAdminPortal())?'admin-login':'home';render()}
async function renderDashboard(){let exams=[],results=[];try{[exams,results]=await Promise.all([api('/api/exams'),api('/api/results')])}catch(x){showToast(x.message)}const passed=results.filter(r=>r.passed).length;const avg=results.length?results.reduce((a,r)=>a+Number(r.percentage||0),0)/results.length:0;app.innerHTML=layout(`<main class="student-dashboard page"><section class="student-hero"><div><div class="eyebrow">Student workspace</div><h1>Welcome back,<br><span>${esc(state.me.user.fullName)}</span></h1><p class="muted">Student ID · <b>${esc(state.me.user.studentId)}</b></p></div><div class="student-id-card"><span>STUDENT ID</span><b>${esc(state.me.user.studentId)}</b><small>Ready for your next assessment</small></div></section><section class="student-stats"><div class="card student-stat"><span>Available exams</span><b>${exams.length}</b><small>Ready to start</small></div><div class="card student-stat"><span>Completed</span><b>${results.length}</b><small>Assessments</small></div><div class="card student-stat"><span>Average score</span><b>${avg.toFixed(1)}%</b><small>${passed} passed</small></div></section><section class="section-head dashboard-section-head"><div><div class="eyebrow">Assessments</div><h2>Available exams</h2></div><span class="muted small-text">Choose an assessment to begin</span></section><section class="grid grid-3 student-exams">${exams.length?exams.map(examCard).join(''):`<div class="card empty">No active exams are available right now.</div>`}</section><section class="section-head dashboard-section-head"><div><div class="eyebrow">Performance</div><h2>My results</h2></div></section><div class="card results-card">${results.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Exam</th><th>Score</th><th>Percentage</th><th>Status</th><th>Date</th></tr></thead><tbody>${results.map(r=>`<tr><td><b>${esc(r.title)}</b></td><td>${r.score} / ${r.total_points}</td><td>${Number(r.percentage).toFixed(1)}%</td><td><span class="pill ${r.passed?'pass':'fail'}">${r.passed?'Passed':'Not passed'}</span></td><td>${fmtDate(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Your completed exams will appear here.</div>`}</div></main>`)}
function examCard(e){const files=Array.isArray(e.attachments)?e.attachments.length:0;return `<article class="card exam-card"><div class="exam-card-top"><span class="pill ${e.status==='active'?'active':''}">${e.status}</span>${Number(e.desktop_required)===1?'<span class="device-badge">Desktop required</span>':''}</div><h3>${esc(e.title)}</h3><p class="muted">${esc(e.description||'Finance assessment')}</p><div class="exam-meta"><span>${e.question_count} questions</span><span>·</span><span>${e.duration_minutes} min</span><span>·</span><span>Pass ${e.passing_percentage}%</span>${files?`<span>·</span><span>${files} file${files===1?'':'s'}</span>`:''}</div><button class="btn orange" onclick="startExam(${e.id})">Start Exam ↗</button></article>`}
async function startExam(id){
  try{
    clearInterval(state.timer);
    state.submitting=false;
    state.expired=false;
    state.answers={};
    state.questions=[];
    state.currentQuestion=0;
    state.reviewMode=false;
    state.skippedQuestions=[];
    const d=await api(`/api/exams/${id}/start`);
    if(!d?.exam) throw new Error('Exam data could not be loaded');
    if(!Array.isArray(d.questions)) throw new Error('Exam questions could not be loaded');
    if(!d.attemptId) throw new Error('Exam attempt could not be created');
    state.exam=d.exam;
    state.questions=d.questions;
    state.attemptId=d.attemptId;
    state.startedAt=d.startedAt;
    state.view='exam';
    renderExam();
    startTimer();
  }catch(x){
    console.error('START EXAM ERROR:',x);
    if(x.message==='لا يمكن دخول الامتحان مرة أخرى لأنك اجتزت هذا الامتحان بالفعل.')showToast('لا يمكن دخول الامتحان مرة أخرى — لقد اجتزت هذا الامتحان بالفعل.');
    else if(x.message==='This assessment must be taken on a desktop or laptop.')showToast('This assessment must be taken on a desktop or laptop.');
    else showToast(x.message||'Unable to start exam');
  }
}
function examAnsweredCount(){return state.questions.filter(q=>state.answers[q.id]).length}
function examUnanswered(){return state.questions.map((q,i)=>({q,i})).filter(x=>!state.answers[x.q.id])}
function answerQuestion(questionId,answer){state.answers[questionId]=answer;state.skippedQuestions=state.skippedQuestions.filter(i=>state.questions[i]?.id!==questionId);renderExam()}
function nextQuestion(){
  const q=state.questions[state.currentQuestion];
  if(q&&!state.answers[q.id])state.skippedQuestions=[...new Set([...state.skippedQuestions,state.currentQuestion])];
  if(state.currentQuestion<state.questions.length-1){state.currentQuestion++;renderExam();return}
  state.reviewMode=true;renderExam();
}
function previousQuestion(){if(state.currentQuestion>0){state.currentQuestion--;state.reviewMode=false;renderExam()}}
function jumpToQuestion(index){if(index<0||index>=state.questions.length)return;state.currentQuestion=index;state.reviewMode=false;renderExam()}
function renderExam(){
  if(Number(state.exam?.desktop_required)===1 && /Mobi|Android|iPhone|iPad|iPod|Windows Phone/i.test(navigator.userAgent||'')){showDesktopRequiredModal();return}
  const total=state.questions.length, answered=examAnsweredCount(), unanswered=examUnanswered();
  if(!total){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card empty">No questions are available for this assessment.</div></div></main>`);return}
  if(state.reviewMode){
    const missing=unanswered;
    app.innerHTML=layout(`<main class="page"><div class="center"><div class="exam-top"><div><div class="eyebrow">Active assessment</div><b>${esc(state.exam.title)}</b></div><div class="timer" id="timer">--:--</div></div><section class="exam-review card"><div class="eyebrow">Final review</div><h1>Review your answers.</h1><p class="muted">You must answer every question before you can submit this assessment.</p><div class="review-stats"><div><b>${answered}</b><span>Answered</span></div><div><b>${total-answered}</b><span>Remaining</span></div></div>${missing.length?`<div class="review-warning"><b>${missing.length} question${missing.length===1?'':'s'} still need an answer.</b><span>Return to each question below before submitting.</span></div>`:`<div class="review-ready"><b>All questions are answered.</b><span>You can submit your assessment now.</span></div>`}<div class="review-question-list">${state.questions.map((q,i)=>{const done=!!state.answers[q.id];return `<button type="button" class="review-question ${done?'is-answered':'is-missing'}" onclick="jumpToQuestion(${i})"><span>Q${i+1}</span><strong>${done?'Answered':'Needs answer'}</strong><em>${done?'✓':'!'}</em></button>`}).join('')}</div><div class="actions exam-actions"><button type="button" class="btn ghost" onclick="jumpToQuestion(${missing.length?missing[0].i:total-1})">${missing.length?'Return to unanswered':'Review last question'}</button><button type="button" class="btn orange" ${missing.length?'disabled':''} onclick="submitExam()">Submit Exam</button><button type="button" class="btn ghost" onclick="if(confirm('Leave the exam? Your in-progress attempt will remain until its timer expires.'))go('dashboard')">Leave</button></div></section></div></main>`);
    return;
  }
  const i=Math.max(0,Math.min(total-1,state.currentQuestion));state.currentQuestion=i;const q=state.questions[i];const files=Array.isArray(q.attachments)?q.attachments:[];const filesHtml=files.length?`<div class="question-files"><div class="small-text muted">Question resources</div><div class="exam-file-list">${files.map((f,j)=>`<div class="exam-file"><div class="file-icon">↧</div><div class="file-info"><b>${esc(f.name)}</b><span class="small-text muted">File ${j+1}</span></div><a class="btn small ghost" href="${esc(f.url)}" target="_blank" rel="noopener noreferrer" download>Download</a></div>`).join('')}</div></div>`:'';
  const progress=total?((i+1)/total)*100:0;
  app.innerHTML=layout(`<main class="page"><div class="center"><div class="exam-top"><div><div class="eyebrow">Active assessment</div><b>${esc(state.exam.title)}</b></div><div class="timer" id="timer">--:--</div></div><section class="exam-progress card"><div><span>Question ${i+1} of ${total}</span><b>${answered} / ${total} answered</b></div><div class="progress-track"><span style="width:${progress}%"></span></div></section><section class="question exam-question"><div class="small-text muted">Question ${i+1} · ${q.points} point${q.points==1?'':'s'}</div><div class="question-title">${esc(q.question_text)}</div>${filesHtml}<div class="options">${['A','B','C','D'].map(k=>`<label class="option"><input type="radio" name="currentQuestion" value="${k}" ${state.answers[q.id]===k?'checked':''} onchange="answerQuestion(${q.id},'${k}')"> <b>${k}.</b> <span>${esc(q['option_'+k.toLowerCase()])}</span></label>`).join('')}</div></section><div class="exam-navigation"><button type="button" class="btn ghost" onclick="previousQuestion()" ${i===0?'disabled':''}>Previous</button><div class="exam-nav-center"><span>${state.answers[q.id]?'Answered':'Not answered'}</span>${!state.answers[q.id]?'<small>You can skip this question and return to it during final review.</small>':''}</div><button type="button" class="btn orange" onclick="nextQuestion()">${!state.answers[q.id]?(i===total-1?'Skip & Review':'Skip & Next'):(i===total-1?'Review & Submit':'Next Question')}</button></div><div class="exam-footer-actions"><button type="button" class="btn ghost" onclick="state.reviewMode=true;renderExam()">Review answers (${answered}/${total})</button><button type="button" class="btn ghost" onclick="if(confirm('Leave the exam? Your in-progress attempt will remain until its timer expires.'))go('dashboard')">Leave</button></div></div></main>`);
}
function showDesktopRequiredModal(){openModal(`<div class="device-warning"><div class="device-warning-icon"><span>▣</span></div><div class="eyebrow">Device requirement</div><h2>Desktop or laptop required</h2><p class="muted">This assessment contains case-study material that is designed for a larger screen. You cannot start it from a phone or tablet.</p><div class="device-warning-points"><span><b>01</b> Better case-study visibility</span><span><b>02</b> Easier document and spreadsheet review</span><span><b>03</b> More comfortable answer navigation</span></div><div class="device-warning-note">Please open this assessment from a desktop or laptop to continue.</div><div class="actions"><button class="btn orange" onclick="closeModal();go('dashboard')">Back to Dashboard</button></div></div>`)}
function startTimer(){
  clearInterval(state.timer);
  if(!state.exam||!state.startedAt){
    console.error('Timer data missing',state.exam,state.startedAt);
    return;
  }
  const raw=String(state.startedAt);
  const normalized=raw.includes('T')?raw:raw.replace(' ','T');
  const parsed=Date.parse(normalized.endsWith('Z')?normalized:`${normalized}Z`);
  const duration=Number(state.exam.duration_minutes);
  if(!Number.isFinite(parsed)||!Number.isFinite(duration)||duration<=0){
    console.error('Invalid timer values:',state.startedAt,state.exam.duration_minutes);
    const el=document.getElementById('timer');
    if(el)el.textContent='--:--';
    return;
  }
  const end=parsed+(duration*60000);
  const tick=()=>{
    if(state.view!=='exam'){
      clearInterval(state.timer);
      return;
    }
    const left=Math.max(0,end-Date.now());
    const minutes=Math.floor(left/60000);
    const seconds=Math.floor(left/1000)%60;
    const el=document.getElementById('timer');
    if(el)el.textContent=`${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;
    if(left<=0&&!state.submitting){
      clearInterval(state.timer);
      state.expired=true;
      submitExam(null,true);
    }
  };
  tick();
  state.timer=setInterval(tick,1000);
}
async function submitExam(e,expired=false){
  if(e) e.preventDefault();
  if(state.submitting) return;
  if(!state.attemptId){showToast('Exam attempt is missing');return}
  const unanswered=examUnanswered();
  if(!expired&&unanswered.length){
    state.reviewMode=true;state.currentQuestion=unanswered[0].i;renderExam();showToast(`Please answer all ${unanswered.length} remaining question${unanswered.length===1?'':'s'} before submitting.`);return;
  }
  if(!expired&&!confirm('Submit this exam now?')) return;
  state.submitting=true;clearInterval(state.timer);
  const answers=Object.entries(state.answers).map(([questionId,answer])=>({questionId:Number(questionId),answer}));
  try{
    const d=await api(`/api/attempts/${state.attemptId}/submit`,{method:'POST',body:JSON.stringify({answers,expired})});
    if(!d?.result) throw new Error('The exam was submitted but no result was returned');
    state.lastResult=d.result;state.view='result';renderResult(d.result);
  }catch(x){
    console.error('SUBMIT EXAM ERROR:',x);state.submitting=false;showToast(x.message||'Unable to submit the exam');
    if(state.view==='exam')renderExam();
  }
}
function renderResult(r){
  const pct=Math.max(0,Math.min(100,Number(r.percentage)||0));
  const ar=state.lang==='ar';
  const passed=!!r.passed;
  const statusText=passed?(ar?'ناجح':'Passed'):(ar?'لم ينجح':'Not passed');
  const message=passed?(ar?'لقد اجتزت هذا الامتحان بنجاح.':'You passed this assessment.'):(ar?'لم تصل إلى درجة النجاح هذه المرة. استمر في التدريب وحاول مرة أخرى.':'You did not reach the passing mark this time. Keep practicing and try again.');
  app.innerHTML=layout(`<main class="page result-page"><div class="result-shell">
    <div class="result-header"><div><div class="eyebrow">${ar?'اكتمل الامتحان':'Assessment complete'}</div><h1>${esc(r.examTitle)}</h1><p class="muted">${ar?'النتيجة النهائية':'Overall score'} · ${fmtDate(r.submittedAt||new Date().toISOString())}</p></div><span class="result-status ${passed?'is-pass':'is-fail'}"><span class="status-dot"></span>${statusText}</span></div>
    <section class="result-hero card">
      <div class="score-ring" style="--score:${pct}%"><div class="score-ring-inner"><strong>${pct.toFixed(1)}%</strong><span>${ar?'النتيجة':'Score'}</span></div></div>
      <div class="result-summary"><div class="eyebrow">${ar?'أداءك':'Your performance'}</div><h2>${message}</h2><p class="muted">${ar?'هذه النتيجة محسوبة تلقائياً بناءً على إجاباتك ودرجة النجاح المحددة للامتحان.':'This result was calculated automatically from your answers and the exam passing requirement.'}</p></div>
    </section>
    <section class="result-metrics">
      <div class="result-metric card"><span>${ar?'النقاط المحصلة':'Points earned'}</span><strong>${r.score} <small>/ ${r.totalPoints}</small></strong></div>
      <div class="result-metric card"><span>${ar?'درجة النجاح':'Pass mark'}</span><strong>${Number(r.passingPercentage??0).toFixed(0)}%</strong></div>
      <div class="result-metric card"><span>${ar?'الأسئلة المُجاب عنها':'Questions answered'}</span><strong>${r.answeredCount??'—'} <small>/ ${r.questionCount??'—'}</small></strong></div>
    </section>
    <div class="result-actions">${!passed&&r.examId?`<button class="btn orange" onclick="startExam(${Number(r.examId)})">${ar?'إعادة الامتحان':'Retake Exam'} ↗</button>`:''}<button class="btn ghost" onclick="go('dashboard')">${ar?'العودة إلى لوحة التحكم':'Back to Dashboard'} ↗</button></div>
  </div></main>`);
  if(state.lang==='ar')translateUI();
}
async function renderAdmin(){app.innerHTML=layout(`<div class="admin-layout"><aside class="sidebar"><button class="side-btn ${state.adminTab==='overview'?'active':''}" onclick="adminTab('overview')">Overview</button><button class="side-btn ${state.adminTab==='students'?'active':''}" onclick="adminTab('students')">Students</button><button class="side-btn ${state.adminTab==='exams'?'active':''}" onclick="adminTab('exams')">Exams</button><button class="side-btn ${state.adminTab==='results'?'active':''}" onclick="adminTab('results')">Results</button>${state.me.admin.role==='super_admin'?`<button class="side-btn ${state.adminTab==='admins'?'active':''}" onclick="adminTab('admins')">Admin Users</button>`:''}</aside><main class="admin-main" id="admin-main"></main></div>`);await loadAdminTab()}
function adminTab(t){state.adminTab=t;renderAdmin()}
async function loadAdminTab(){const el=document.getElementById('admin-main');if(state.adminTab==='overview')return adminOverview(el);if(state.adminTab==='students')return adminStudents(el);if(state.adminTab==='exams')return adminExams(el);if(state.adminTab==='results')return adminResults(el);if(state.adminTab==='admins')return adminAdmins(el)}
async function adminOverview(el){const d=await api('/api/admin/stats');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Control center</div><h1>Overview</h1><p class="muted">Manage the assessment platform.</p></div></div><div class="kpis"><div class="card kpi"><div class="muted">Students</div><div class="num">${d.students}</div></div><div class="card kpi"><div class="muted">Exams</div><div class="num">${d.exams}</div></div><div class="card kpi"><div class="muted">Attempts</div><div class="num">${d.attempts}</div></div><div class="card kpi"><div class="muted">Avg. score</div><div class="num">${d.averagePercentage.toFixed(1)}%</div></div></div><div class="grid grid-2 admin-section"><div class="card"><div class="eyebrow">Pass rate</div><div class="score" style="font-size:48px">${d.passRate.toFixed(1)}%</div><p class="muted">Across completed attempts.</p></div><div class="card"><h3>Admin</h3><p class="muted">Signed in as <b>${esc(state.me.admin.username)}</b> · ${esc(state.me.admin.role)}</p><button class="btn ghost" onclick="adminTab('exams')">Manage exams →</button></div></div>`}
async function adminStudents(el){const rows=await api('/api/admin/students');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">People</div><h1>Students</h1></div><div class="toolbar"><input id="studentSearch" placeholder="Search students…" oninput="searchStudents()"></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Student ID</th><th>Name</th><th>Email</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody id="students-body">${studentRows(rows)}</tbody></table></div></div>`}
function studentRows(rows){return rows.map(r=>`<tr><td><button type="button" class="copy-id" title="Copy student ID" onclick="copyStudentId('${esc(r.student_id).replaceAll("'","&#39;")}')"><b>${esc(r.student_id)}</b><span>⧉</span></button></td><td><b>${esc(r.full_name)}</b></td><td>${esc(r.email)}</td><td><span class="pill">${r.status}</span></td><td>${fmtDate(r.created_at)}</td><td><button class="btn small ghost" onclick="studentDetail(${r.id})">Manage</button></td></tr>`).join('')||`<tr><td colspan="6" class="empty">No students found.</td></tr>`}
async function copyStudentId(id){try{await navigator.clipboard.writeText(id);showToast(`Copied ${id}`)}catch{const t=document.createElement('textarea');t.value=id;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();showToast(`Copied ${id}`)}}
let searchTimer;async function searchStudents(){clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const q=document.getElementById('studentSearch').value;const rows=await api('/api/admin/students?q='+encodeURIComponent(q));document.getElementById('students-body').innerHTML=studentRows(rows)},250)}
async function studentDetail(id){const d=await api(`/api/admin/students/${id}`);openModal(`<div class="modal-head"><div><div class="eyebrow">Student account</div><h2>${esc(d.student.full_name)}</h2><p class="muted">Manage access, credentials and exam history.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="grid grid-2"><div class="card student-account-card"><div class="account-id-label">Student ID</div><button type="button" class="account-id" onclick="copyStudentId('${esc(d.student.student_id).replaceAll("'","&#39;")}')"><strong>${esc(d.student.student_id)}</strong><span>Copy</span></button><p>${esc(d.student.email)}</p><span class="pill">${d.student.status}</span><div class="actions" style="margin-top:15px"><button class="btn small ${d.student.status==='active'?'danger':'orange'}" onclick="toggleStudent(${id},'${d.student.status==='active'?'blocked':'active'}')">${d.student.status==='active'?'Block student':'Activate student'}</button><button class="btn small orange" onclick="resetStudentPassword(${id},'${esc(d.student.full_name).replaceAll("'","&#39;")}')">Change password</button></div></div><div class="card"><b>Exam results</b>${d.results.length?`<div class="stack" style="margin-top:12px">${d.results.map(r=>`<div class="statline"><span>${esc(r.title)}</span><span>${Number(r.percentage).toFixed(1)}%</span></div>`).join('')}</div>`:`<p class="muted">No results yet.</p>`}</div></div>`)}
async function resetStudentPassword(id,name){openModal(`<div class="modal-head"><div><div class="eyebrow">Account security</div><h2>Change student password</h2><p class="muted">Set a new password for ${esc(name)}. The student will need to sign in again.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveStudentPassword(event,${id})"><div class="field"><label>New password</label><input name="newPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required placeholder="At least 8 characters"></div><div class="field"><label>Confirm password</label><input name="confirmPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required placeholder="Repeat the new password"></div><div class="card security-note"><b>Admin action</b><span>The student's existing sessions will be signed out after the password is changed.</span></div><div class="actions"><button type="button" class="btn ghost" onclick="studentDetail(${id})">Cancel</button><button class="btn orange">Update password</button></div></form>`)}
async function saveStudentPassword(e,id){e.preventDefault();const fd=new FormData(e.target),newPassword=String(fd.get('newPassword')||''),confirmPassword=String(fd.get('confirmPassword')||'');if(newPassword!==confirmPassword){showToast('Passwords do not match');return}try{await api(`/api/admin/students/${id}/reset-password`,{method:'POST',body:JSON.stringify({newPassword})});closeModal();showToast('Student password updated');studentDetail(id)}catch(x){showToast(x.message||'Unable to update password')}}
async function toggleStudent(id,status){await api(`/api/admin/students/${id}`,{method:'PATCH',body:JSON.stringify({status})});closeModal();showToast('Student status updated');adminTab('students')}
async function adminExams(el){const rows=await api('/api/admin/exams');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Assessment design</div><h1>Exams</h1></div><button class="btn orange" onclick="examForm()">+ New Exam</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Exam</th><th>Questions</th><th>Duration</th><th>Pass</th><th>Status</th><th>Device</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.title)}</b><div class="small-text muted">${esc(r.description||'')}</div></td><td>${r.question_count}</td><td>${r.duration_minutes} min</td><td>${r.passing_percentage}%</td><td><span class="pill">${r.status}</span></td><td>${Number(r.desktop_required)===1?'<span class="device-badge">Desktop</span>':'<span class="muted small-text">Any device</span>'}</td><td><div class="actions"><button class="btn small ghost" onclick="questionManager(${r.id},'${esc(r.title).replaceAll("'","&#39;")}')">Questions</button><button class="btn small ghost" onclick='examForm(${JSON.stringify(r).replace(/'/g,"&#39;")})'>Edit</button><button class="btn small danger" onclick="deleteExam(${r.id})">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="7" class="empty">No exams.</td></tr>`}</tbody></table></div></div>`}
function attachmentRows(exam){let raw=exam?.attachments||exam?.attachments_json||[];let arr=[];try{arr=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch{};if(!arr.length)arr=[{}];return arr.map(attachmentRow).join('')}
function attachmentRow(a={}){return `<div class="attachment-row"><div class="field"><label>File name</label><input name="attachmentName" maxlength="200" placeholder="e.g. Excel template" value="${esc(a?.name||'')}"></div><div class="field"><label>File URL</label><input name="attachmentUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(a?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.attachment-row').remove()">Remove</button></div>`}
function addAttachmentRow(){document.getElementById('attachmentRows')?.insertAdjacentHTML('beforeend',attachmentRow())}
function examForm(exam=null){openModal(`<div class="modal-head"><div><div class="eyebrow">${exam?'Edit exam':'Create exam'}</div><h2>${exam?'Update assessment':'New assessment'}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveExam(event,${exam?.id||0})"><div class="field"><label>Title</label><input name="title" required value="${esc(exam?.title||'')}"></div><div class="field"><label>Description</label><textarea name="description" rows="3">${esc(exam?.description||'')}</textarea></div><div class="two-col"><div class="field"><label>Duration (minutes)</label><input name="durationMinutes" type="number" min="1" max="600" required value="${exam?.duration_minutes||30}"></div><div class="field"><label>Passing percentage</label><input name="passingPercentage" type="number" min="0" max="100" step="0.1" required value="${exam?.passing_percentage??50}"></div></div><div class="field"><label>Status</label><select name="status"><option value="active" ${exam?.status==='active'?'selected':''}>Active</option><option value="inactive" ${exam?.status!=='active'?'selected':''}>Inactive</option></select></div><label class="switch-field"><input type="checkbox" name="desktopRequired" ${Number(exam?.desktop_required)===1?'checked':''}><span><b>Require desktop / laptop</b><small>Show a warning and prevent this exam from starting on phones and tablets.</small></span></label><div class="card" style="padding:16px;background:var(--surface2)"><div class="eyebrow">Question resources</div><p class="small-text muted" style="margin:6px 0 0">Add files inside each question. A file will appear only with the question it belongs to.</p></div><button class="btn orange">Save Exam</button></form>`)}
async function saveExam(e,id){e.preventDefault();const fd=new FormData(e.target);const data={title:fd.get('title'),description:fd.get('description'),durationMinutes:fd.get('durationMinutes'),passingPercentage:fd.get('passingPercentage'),status:fd.get('status'),desktopRequired:fd.get('desktopRequired')==='on'};try{await api(id?`/api/admin/exams/${id}`:'/api/admin/exams',{method:id?'PUT':'POST',body:JSON.stringify(data)});closeModal();showToast('Exam saved');adminTab('exams')}catch(x){showToast(x.message)}}
async function deleteExam(id){if(!confirm('Delete this exam and all its questions/results?'))return;try{await api(`/api/admin/exams/${id}`,{method:'DELETE'});showToast('Exam deleted');adminTab('exams')}catch(x){showToast(x.message)}}
async function questionManager(examId,title){const qs=await api(`/api/admin/exams/${examId}/questions`);openModal(`<div class="modal-head"><div><div class="eyebrow">Question bank</div><h2>${esc(title)}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="actions" style="margin-bottom:15px"><button class="btn orange" onclick="questionForm(${examId},null,'${esc(title).replaceAll("'","&#39;")}')">+ Add Question</button></div><div class="stack">${qs.map((q,i)=>{const files=Array.isArray(q.attachments)?q.attachments:[];return `<div class="card"><div class="small-text muted">Question ${i+1} · ${q.points} point${q.points==1?'':'s'} · Correct answer ${q.correct_answer}</div><b>${esc(q.question_text)}</b><p class="small-text muted">A. ${esc(q.option_a)} · B. ${esc(q.option_b)} · C. ${esc(q.option_c)} · D. ${esc(q.option_d)}</p>${files.length?`<div class="small-text"><b>Resources:</b> ${files.map(f=>esc(f.name)).join(' · ')}</div>`:''}<div class="actions"><button class="btn small ghost" onclick='questionForm(${examId},${JSON.stringify(q).replace(/'/g,"&#39;")},"${esc(title).replaceAll('"','&quot;')}")'>Edit</button><button class="btn small danger" onclick="deleteQuestion(${q.id},${examId},'${esc(title).replaceAll("'","&#39;")}')">Delete</button></div></div>`}).join('')||`<div class="empty">No questions yet.</div>`}</div>`)}
function questionAttachmentRows(q){let raw=q?.attachments||q?.attachments_json||[];let arr=[];try{arr=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch{};if(!arr.length)arr=[{}];return arr.map(questionAttachmentRow).join('')}
function questionAttachmentRow(a={}){return `<div class="attachment-row question-attachment-row"><div class="field"><label>File name</label><input name="questionAttachmentName" maxlength="200" placeholder="e.g. Case study 1" value="${esc(a?.name||'')}"></div><div class="field"><label>File URL</label><input name="questionAttachmentUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(a?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.question-attachment-row').remove()">Remove</button></div>`}
function addQuestionAttachmentRow(){document.getElementById('questionAttachmentRows')?.insertAdjacentHTML('beforeend',questionAttachmentRow())}
function questionForm(examId,q,title){openModal(`<div class="modal-head"><div><div class="eyebrow">${q?'Edit question':'Add question'}</div><h2>${esc(title)}</h2></div><button class="icon-btn" onclick="questionManager(${examId},'${esc(title).replaceAll("'","&#39;")}')">×</button></div><form class="form" onsubmit="saveQuestion(event,${examId},${q?.id||0},'${esc(title).replaceAll("'","&#39;")}')"><div class="field"><label>Question</label><textarea name="questionText" rows="4" required>${esc(q?.question_text||'')}</textarea></div><div class="two-col"><div class="field"><label>Option A</label><input name="optionA" required value="${esc(q?.option_a||'')}"></div><div class="field"><label>Option B</label><input name="optionB" required value="${esc(q?.option_b||'')}"></div><div class="field"><label>Option C</label><input name="optionC" required value="${esc(q?.option_c||'')}"></div><div class="field"><label>Option D</label><input name="optionD" required value="${esc(q?.option_d||'')}"></div></div><div class="two-col"><div class="field"><label>Correct answer</label><select name="correctAnswer">${['A','B','C','D'].map(x=>`<option ${q?.correct_answer===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Points</label><input name="points" type="number" min="0.1" step="0.1" value="${q?.points||1}"></div></div><div class="field"><label>Sort order</label><input name="sortOrder" type="number" value="${q?.sort_order||0}"></div><div class="attachment-admin"><div class="section-head" style="margin:8px 0 12px"><div><div class="eyebrow">Question resources</div><h3 style="margin:4px 0 0">Files for this question</h3></div><button type="button" class="btn small ghost" onclick="addQuestionAttachmentRow()">+ Add file</button></div><p class="small-text muted">These files will appear only with this specific question during the exam.</p><div id="questionAttachmentRows" class="attachment-rows">${questionAttachmentRows(q)}</div></div><button class="btn orange">Save Question</button></form>`)}
async function saveQuestion(e,examId,id,title){e.preventDefault();const fd=new FormData(e.target);const names=fd.getAll('questionAttachmentName'),urls=fd.getAll('questionAttachmentUrl');const data=Object.fromEntries(fd);data.examId=examId;data.attachments=names.map((name,i)=>({name:String(name||'').trim(),url:String(urls[i]||'').trim()})).filter(x=>x.name&&x.url);try{await api(id?`/api/admin/questions/${id}`:'/api/admin/questions',{method:id?'PUT':'POST',body:JSON.stringify(data)});await questionManager(examId,title);showToast('Question saved')}catch(x){showToast(x.message)}}
async function deleteQuestion(id,examId,title){if(!confirm('Delete this question?'))return;await api(`/api/admin/questions/${id}`,{method:'DELETE'});await questionManager(examId,title);showToast('Question deleted')}

async function adminResults(el){const rows=await api('/api/admin/results');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Performance</div><h1>Results</h1></div><div class="toolbar"><input id="resultSearch" placeholder="Search results…" oninput="searchResults()"></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Exam</th><th>Score</th><th>Percentage</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody id="results-body">${resultRows(rows)}</tbody></table></div></div>`}
function resultRows(rows){return rows.map(r=>`<tr><td><b>${esc(r.student_id)}</b><div class="small-text muted">${esc(r.full_name)}</div></td><td>${esc(r.title)}</td><td>${r.score}/${r.total_points}</td><td>${Number(r.percentage).toFixed(1)}%</td><td><span class="pill ${r.passed?'pass':'fail'}">${r.passed?'Passed':'Not passed'}</span></td><td>${fmtDate(r.created_at)}</td><td><button class="btn small ghost" onclick="resultDetail(${r.id})">View</button></td></tr>`).join('')||`<tr><td colspan="7" class="empty">No results.</td></tr>`}
let resultTimer;async function searchResults(){clearTimeout(resultTimer);resultTimer=setTimeout(async()=>{const q=document.getElementById('resultSearch').value;const rows=await api('/api/admin/results?q='+encodeURIComponent(q));document.getElementById('results-body').innerHTML=resultRows(rows)},250)}
async function resultDetail(id){const d=await api(`/api/admin/results/${id}`);openModal(`<div class="modal-head"><div><div class="eyebrow">Result detail</div><h2>${esc(d.result.title)}</h2><p class="muted">${esc(d.result.student_id)} · ${esc(d.result.full_name)}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="grid grid-3"><div class="card"><b>Score</b><div class="score" style="font-size:35px">${Number(d.result.percentage).toFixed(1)}%</div></div><div class="card"><b>Points</b><p>${d.result.score} / ${d.result.total_points}</p></div><div class="card"><b>Status</b><p class="${d.result.passed?'success-text':'danger-text'}">${d.result.passed?'Passed':'Not passed'}</p></div></div><div class="stack" style="margin-top:16px">${d.answers.map((a,i)=>`<div class="card"><b>${i+1}. ${esc(a.question_text)}</b><p class="small-text">Selected: ${a.selected_answer||'No answer'} · Correct: ${a.correct_answer} · ${a.is_correct?'Correct':'Incorrect'}</p></div>`).join('')}</div>`)}
async function adminAdmins(el){const rows=await api('/api/admin/admins');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Access control</div><h1>Admin users</h1></div><button class="btn orange" onclick="adminForm()">+ Add Admin</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Username</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.username)}</b></td><td>${esc(r.role)}</td><td><span class="pill">${r.status}</span></td><td>${fmtDate(r.created_at)}</td><td>${r.id!==undefined?`<button class="btn small ghost" onclick="toggleAdmin(${r.id},'${r.status==='active'?'blocked':'active'}')">${r.status==='active'?'Block':'Activate'}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`}
function adminForm(){openModal(`<div class="modal-head"><div><div class="eyebrow">Access control</div><h2>Add admin</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveAdmin(event)"><div class="field"><label>Username</label><input name="username" pattern="[A-Za-z0-9._\-]{3,80}" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>Role</label><select name="role"><option value="admin">Admin</option><option value="super_admin">Super admin</option></select></div><button class="btn orange">Create Admin</button></form>`)}
async function saveAdmin(e){e.preventDefault();try{await api('/api/admin/admins',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();showToast('Admin created');adminTab('admins')}catch(x){showToast(x.message)}}
async function toggleAdmin(id,status){await api(`/api/admin/admins/${id}`,{method:'PATCH',body:JSON.stringify({status})});showToast('Admin status updated');adminTab('admins')}
function openModal(html){const d=document.createElement('div');d.id='modal';d.className='modal-backdrop';d.innerHTML=`<div class="modal">${html}</div>`;document.body.appendChild(d)}function closeModal(){document.getElementById('modal')?.remove()}
function toggleLang(){state.lang=state.lang==='en'?'ar':'en';localStorage.setItem('exam_lang',state.lang);document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';render()}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('exam_theme',state.theme);applyTheme();render()}
function applyTheme(){document.body.classList.toggle('dark-mode',state.theme==='dark');document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr'}
function go(v){if(v==='admin-login'){location.href='/admin';return}if(v==='home'){if(location.pathname!=='/admin.html'&&location.pathname!=='/admin')state.view='home';else state.adminTab='overview'}else if(v==='results'){state.view=state.me?.user?'dashboard':'login'}else if(v==='dashboard'&&!state.me?.user){state.view='login'}else state.view=v;if(v!=='exam')clearInterval(state.timer);render()}
window.go=go;window.answerQuestion=answerQuestion;window.nextQuestion=nextQuestion;window.previousQuestion=previousQuestion;window.jumpToQuestion=jumpToQuestion;window.toggleLang=toggleLang;window.toggleTheme=toggleTheme;window.adminLogin=adminLogin;window.studentLogin=studentLogin;window.studentRegister=studentRegister;window.logout=logout;window.startExam=startExam;window.submitExam=submitExam;window.adminTab=adminTab;window.searchStudents=searchStudents;window.studentDetail=studentDetail;window.toggleStudent=toggleStudent;window.examForm=examForm;window.addAttachmentRow=addAttachmentRow;window.addQuestionAttachmentRow=addQuestionAttachmentRow;window.saveExam=saveExam;window.deleteExam=deleteExam;window.questionManager=questionManager;window.questionForm=questionForm;window.saveQuestion=saveQuestion;window.deleteQuestion=deleteQuestion;window.searchResults=searchResults;window.resultDetail=resultDetail;window.adminForm=adminForm;window.saveAdmin=saveAdmin;window.toggleAdmin=toggleAdmin;window.closeModal=closeModal;
boot();
